def _dir_format(path: Path) -> str:
    cfg = path / "config.json"
    if cfg.is_file() and '"quantization"' in cfg.read_text(encoding="utf-8", errors="ignore"):
        return "mlx"
    return "hf"


def _check_disk(size: int, cache_dir: str | None) -> None:
    from huggingface_hub import constants

    where = cache_dir or constants.HF_HUB_CACHE
    free = free_disk_bytes(where)
    need = int(size * 1.1)
    if free < need:
        raise ResolveError(
            f"Not enough disk space in {where}: need about {human_size(need)}, "
            f"{human_size(free)} free. Set HF_HOME to a bigger drive."
        )
    print(f"Downloading to {where} ({human_size(size)}, {human_size(free)} free)")

"""GGUF backend through llama-cpp-python (needs `quantgap[llamacpp]`).

Verified fact (docs/DECISIONS.md, M0): `Llama(..., logits_all=True)` followed by `eval(tokens)`
fills `llm.scores`, an array of shape (n_ctx, n_vocab). Row i holds the logits that come out
after reading token i, so it predicts token i + 1.
"""

from __future__ import annotations

from typing import Any

import numpy as np

from quantgap.backends.base import (
    BackendSettings,
    PromptLogprobs,
    ResolvedSource,
    gather_from_logits,
)
from quantgap.tokcheck import CHECK_STRING, TokFingerprint


class LlamaCppBackend:
    name = "llamacpp"

    def __init__(self) -> None:
        self.llm: Any = None
        self.settings: BackendSettings | None = None

    def load(self, source: ResolvedSource, settings: BackendSettings) -> None:
        try:
            from llama_cpp import Llama
        except ImportError as e:  # pragma: no cover
            raise RuntimeError(
                'llama-cpp-python is not installed. Run: pip install "quantgap[llamacpp]"'
            ) from e
        if source.path is None or not source.path.is_file():
            raise FileNotFoundError(f"GGUF file not found: {source.path}")
        self.settings = settings
        kwargs: dict[str, Any] = {
            "model_path": str(source.path),
            "n_ctx": settings.ctx,
            "n_gpu_layers": settings.n_gpu_layers,
            "logits_all": True,
            "verbose": False,
        }
        if settings.n_threads:
            kwargs["n_threads"] = settings.n_threads
        self.llm = Llama(**kwargs)

    def tokenizer_fingerprint(self) -> TokFingerprint:
        llm = self.llm
        ids = llm.tokenize(CHECK_STRING.encode("utf-8"), add_bos=False, special=False)
        return TokFingerprint(
            vocab_size=int(llm.n_vocab()),
            bos_id=int(llm.token_bos()) if llm.token_bos() >= 0 else None,
            eos_id=int(llm.token_eos()) if llm.token_eos() >= 0 else None,
            check_ids=[int(i) for i in ids],
        )

    def prompt_logprobs(
        self, token_ids: list[int], positions: np.ndarray, gather_ids: np.ndarray
    ) -> PromptLogprobs:
        llm = self.llm
        llm.reset()
        llm.eval(token_ids)
        positions = np.asarray(positions)
        rows = np.asarray(llm.scores[positions], dtype=np.float32)
        tgt = np.asarray(token_ids, dtype=np.int64)[positions + 1]
        return gather_from_logits(rows, tgt, gather_ids)

    def generate_greedy(self, token_ids: list[int], max_new_tokens: int) -> list[int]:
        llm = self.llm
        llm.reset()
        out: list[int] = []
        eos = llm.token_eos()
        for tok in llm.generate(token_ids, top_k=1, top_p=1.0, temp=0.0, reset=True):
            if tok == eos or len(out) >= max_new_tokens:
                break
            out.append(int(tok))
        return out

    def decode(self, ids: list[int]) -> str:
        return self.llm.detokenize(ids).decode("utf-8", errors="replace")

    def version(self) -> str:
        import llama_cpp

        return f"llama-cpp-python {llama_cpp.__version__}"

    def close(self) -> None:
        if self.llm is not None:
            self.llm.close()
            self.llm = None

class MLXBackend:
    name = "mlx"

    def __init__(self) -> None:
        self.model: Any = None
        self.tok: Any = None

    def load(self, source: ResolvedSource, settings: BackendSettings) -> None:
        try:
            from mlx_lm import load
        except ImportError as e:  # pragma: no cover
            raise RuntimeError('mlx-lm is not installed. Run: pip install "quantgap[mlx]"') from e
        where = str(source.path) if source.path else source.source.removeprefix("hf://")
        self.model, self.tok = load(where)

    def _hf_tok(self) -> Any:
        return getattr(self.tok, "_tokenizer", self.tok)

    def tokenizer_fingerprint(self) -> TokFingerprint:
        t = self._hf_tok()
        ids = list(t(CHECK_STRING, add_special_tokens=False)["input_ids"])
        vocab = len(t)
        try:  # the real embedding size is what matters for padding ids
            vocab = int(self.model.model.embed_tokens.weight.shape[0])
        except Exception:
            pass
        return TokFingerprint(vocab, t.bos_token_id, t.eos_token_id, ids)

    def prompt_logprobs(
        self, token_ids: list[int], positions: np.ndarray, gather_ids: np.ndarray
    ) -> PromptLogprobs:
        import mlx.core as mx

        logits = self.model(mx.array([token_ids]))[0]
        rows = np.array(logits.astype(mx.float32))[np.asarray(positions)]
        tgt = np.asarray(token_ids, dtype=np.int64)[np.asarray(positions) + 1]
        return gather_from_logits(rows, tgt, gather_ids)

    def generate_greedy(self, token_ids: list[int], max_new_tokens: int) -> list[int]:
        import mlx.core as mx

        ids = list(token_ids)
        out: list[int] = []
        eos = self.tok.eos_token_id
        for _ in range(max_new_tokens):  # no KV cache: slow but simple and exact
            logits = self.model(mx.array([ids]))[0, -1]
            nxt = int(mx.argmax(logits).item())
            if nxt == eos:
                break
            out.append(nxt)
            ids.append(nxt)
        return out

    def decode(self, ids: list[int]) -> str:
        return self.tok.decode(ids)

    def version(self) -> str:
        import mlx_lm

        return f"mlx-lm {getattr(mlx_lm, '__version__', 'unknown')}"

    def close(self) -> None:
        self.model = None
        self.tok = None

def resolve_quant(
    quant: str,
    *,
    base_url: str | None = None,
    model_name: str | None = None,
    compute_hash: bool = True,
) -> ResolvedSource:
    """Find a quant. Downloads from the Hub when given an hf:// URL."""
    if quant.startswith("openai://"):
        if not base_url:
            raise ResolveError("openai:// needs --base-url, for example http://localhost:8000/v1")
        name = quant[len("openai://") :] or (model_name or "")
        return ResolvedSource(
            source=quant,
            label=name or "server-model",
            format="openai",
            extra={"model_name": model_name or name},
        )
    if quant.startswith("hf://"):
        ref = parse_hf_url(quant)
        return _resolve_hf(ref, quant)
    p = Path(quant).expanduser()
    if p.is_file():
        src = ResolvedSource(
            source=str(p),
            label=label_from_filename(p.name) if p.suffix == ".gguf" else p.stem,
            path=p,
            size_bytes=p.stat().st_size,
            format="gguf" if p.suffix.lower() == ".gguf" else "hf",
        )
        if src.format == "gguf":
            src.base_model = gguf_base_model(p)
        if compute_hash:
            src.sha256 = sha256_file(p)
        return src
    if p.is_dir():
        size = sum(f.stat().st_size for f in p.rglob("*") if f.is_file())
        return ResolvedSource(
            source=str(p), label=p.name, path=p, size_bytes=size, format=_dir_format(p)
        )
    raise ResolveError(
        f"Cannot find {quant!r}. Use a local file or folder, hf://org/repo/file.gguf, "
        "or openai://NAME with --base-url."
    )

def _score_source(
    src: ResolvedSource, pack, cfg: Settings, *, backend_name: str, ctx, n_gpu_layers,
    base_url, model_name, groups, quick: bool, do_damage: bool,
) -> ScoreResult:  # fmt: skip
    from quantgap.hub.packs import fine_tune_warning
    from quantgap.score.run import score_quant

    name = backend_name if backend_name != "auto" else pick_backend_name(src, base_url)
    settings = _settings_for(cfg, name, ctx, n_gpu_layers, base_url, model_name)
    warns = []
    if (w := fine_tune_warning(src.base_model, pack)) is not None:
        warns.append(w)
    backend = get_backend(name)
    backend.load(src, settings)
    prog, cb = _progress()
    try:
        with prog:
            return score_quant(
                pack, backend, src, settings, groups=groups, quick=quick,
                do_damage=do_damage, warnings=warns, progress=cb,
            )  # fmt: skip
    finally:
        backend.close()


def _get_pack(pack_ref: str | None, src: ResolvedSource, cfg: Settings):
    from quantgap.hub.packs import auto_find_pack, load_pack

    if pack_ref:
        return load_pack(pack_ref)
    return auto_find_pack(src.base_model, cfg)


def _resolve(quant: str, base_url, model_name) -> ResolvedSource:
    from quantgap.hub.resolve import ResolveError, resolve_quant

    try:
        return resolve_quant(quant, base_url=base_url, model_name=model_name)
    except ResolveError as e:
        hint = OLLAMA_HINT if (":" in quant and "/" not in quant and "\\" not in quant) else ""
        raise _fail(f"{e}\n{hint}".strip()) from e


